// Parse Claude's response and extract JSON
const response = $input.first().json.content[0].text;

let invoiceData;
try {
  // Try direct JSON parse
  invoiceData = JSON.parse(response);
} catch (error) {
  // If wrapped in markdown, extract JSON
  const jsonMatch = response.match(/```json\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    invoiceData = JSON.parse(jsonMatch[1]);
  } else {
    // Try to find any JSON object
    const objMatch = response.match(/\{[\s\S]*\}/);
    if (objMatch) {
      invoiceData = JSON.parse(objMatch[0]);
    } else {
      throw new Error('Could not extract JSON from response');
    }
  }
}

// Add workflow metadata (if available from earlier nodes)
if ($('Manual Trigger').item.json.id) {
  invoiceData.id = $('Manual Trigger').item.json.id;
}
if ($('Manual Trigger').item.json.threadId) {
  invoiceData.threadId = $('Manual Trigger').item.json.threadId;
}

return {
  json: invoiceData
};
